#include "MainComponent.h"
namespace {juce::String u(const char* s){return juce::String::fromUTF8(s);}}
class PolishPanel final : public juce::Component,private juce::Timer {
    StudioMain& owner;juce::Label title,help;juce::TextEditor status;juce::TextButton preset,on,off,listen,exportButton,fx;juce::Slider level,tame,duck;std::array<juce::Label,3> labels;
public:
    explicit PolishPanel(StudioMain& main):owner(main){for(juce::Component* c:std::initializer_list<juce::Component*>{&title,&help,&status,&preset,&on,&off,&listen,&exportButton,&fx,&level,&tame,&duck})addAndMakeVisible(c);title.setText(u("VOCAL STUDIO · ĐỀU GIỌNG / DỊU GẮT / VANG CHÌM"),juce::dontSendNotification);title.setFont(juce::Font(21,juce::Font::bold));help.setText(u("Chỉ xử lý vocal; giữ EQ riêng và thiết lập Antares. Preset Studio chỉnh compressor/vang nhẹ rồi bật ba bước mới.\nBật/Tắt bên dưới chỉ so ba bước mới, không tắt EQ, compressor hoặc Antares."),juce::dontSendNotification);auto button=[](juce::TextButton& b,const char* text,std::function<void()> fn){b.setButtonText(u(text));b.onClick=std::move(fn);};button(preset,"Áp dụng preset Studio",[this]{if(owner.isBusy())return;owner.engine.studioPolish();owner.save();owner.status(u("Đã áp dụng Studio: giữ EQ riêng/Antares, cân mức nhẹ và vang né giọng. Nghe thử trên micro của bạn."));});button(on,"Bật ba bước mới",[this]{if(owner.isBusy())return;owner.engine.leveling=.7f;owner.engine.dynamicTame=.55f;owner.engine.reverbDuck=.65f;});button(off,"Tắt ba bước mới",[this]{if(owner.isBusy())return;owner.engine.leveling=0;owner.engine.dynamicTame=0;owner.engine.reverbDuck=0;});button(listen,"Nghe bản thu với FX",[this]{owner.listenAutoEq();});button(exportButton,"Xuất WAV vocal có FX",[this]{if(owner.isExporting())owner.cancelToolsWork();else owner.exportVocal();});button(fx,"Menu FX chi tiết",[this]{owner.showVocalTools();});juce::Slider* sliders[]={&level,&tame,&duck};const char* names[]={"Cân câu hát nhỏ / to","Dịu gắt động · vùng 3,5 kHz","Vang né giọng khi đang hát"};std::atomic<float>* values[]={&owner.engine.leveling,&owner.engine.dynamicTame,&owner.engine.reverbDuck};for(int i=0;i<3;++i){addAndMakeVisible(labels[i]);labels[i].setText(u(names[i]),juce::dontSendNotification);auto* s=sliders[i];auto* v=values[i];s->setRange(0,100,1);s->setSliderStyle(juce::Slider::LinearHorizontal);s->setTextBoxStyle(juce::Slider::TextBoxRight,false,75,24);s->setTextValueSuffix(" %");s->onValueChange=[this,s,v]{if(!owner.isBusy())*v=static_cast<float>(s->getValue()*.01);};}status.setMultiLine(true);status.setReadOnly(true);status.setScrollbarsShown(true);setSize(820,600);startTimerHz(10);timerCallback();}
    ~PolishPanel() override{stopTimer();}
    void paint(juce::Graphics& g) override{g.fillAll(juce::Colour(0xff10151e));}
    void resized() override{int w=getWidth();title.setBounds(20,12,w-40,36);help.setBounds(20,52,w-40,60);preset.setBounds(20,125,240,34);on.setBounds(275,125,230,34);off.setBounds(520,125,w-540,34);juce::Slider* sliders[]={&level,&tame,&duck};for(int i=0;i<3;++i){labels[i].setBounds(20,181+i*58,285,30);sliders[i]->setBounds(305,181+i*58,w-325,30);}listen.setBounds(20,367,245,34);exportButton.setBounds(280,367,270,34);fx.setBounds(565,367,w-585,34);status.setBounds(20,420,w-40,getHeight()-435);}
    void timerCallback() override{const bool busy=owner.isBusy();level.setEnabled(!busy);tame.setEnabled(!busy);duck.setEnabled(!busy);for(auto* b:{&preset,&on,&off,&fx})b->setEnabled(!busy);listen.setEnabled(!busy&&!owner.engine.isRecording());exportButton.setEnabled(owner.isExporting()||(!busy&&!owner.engine.isRecording()));exportButton.setButtonText(owner.isExporting()?u("Hủy xuất WAV"):u("Xuất WAV vocal có FX"));if(!level.isMouseButtonDown())level.setValue(owner.engine.leveling.load()*100,juce::dontSendNotification);if(!tame.isMouseButtonDown())tame.setValue(owner.engine.dynamicTame.load()*100,juce::dontSendNotification);if(!duck.isMouseButtonDown())duck.setValue(owner.engine.reverbDuck.load()*100,juce::dontSendNotification);auto text=u("Cân mức giới hạn tối đa +4 / −6 dB ở 100%, ngừng nâng gain ở mức rất nhỏ; không phải bộ khử ồn. Dịu gắt giảm có điều kiện, không cắt tối toàn bộ giọng. Vang lùi khi hát, đuôi vang trở lại khi ngắt câu. Không thêm lookahead.\n\nXuất WAV: chọn/thu một vocal trước; chỉ giọng gốc qua FX/Antares hiện tại và đuôi vang, không có nhạc YouTube. Nếu bài đổi key giữa chừng, kiểm tra Key/Scale trước khi xuất. WAV micro gốc giữ nguyên.\n\n")+owner.userStatus();if(owner.engine.fxBypass.load())text=u("VOCAL FX ĐANG BYPASS: bỏ Bypass FX hoặc bấm Áp dụng preset Studio để nghe xử lý.\n\n")+text;if(owner.engine.inputClipped.load())text+=u("\nMIC CLIP: giảm gain vật lý; các bước này không khôi phục hoàn toàn âm đã vỡ.");if(owner.isExporting())text=u("ĐANG XUẤT VOCAL: ")+juce::String(owner.toolsProgress()*100,0)+u("% · Có thể bấm Hủy xuất WAV.\n\n")+text;if(status.getText()!=text)status.setText(text,false);}
};
juce::Component* createPolishPanel(StudioMain& owner){return new PolishPanel(owner);}
